from collections import deque,defaultdict

def zero_components(g):
 R=len(g); C=len(g[0]); seen=set(); comps=[]
 for r in range(R):
  for c in range(C):
   if g[r][c]==0 and (r,c) not in seen:
    q=[(r,c)]; seen.add((r,c)); co=[]
    while q:
     x,y=q.pop(); co.append((x,y))
     for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
      a,b=x+dx,y+dy
      if 0<=a<R and 0<=b<C and g[a][b]==0 and (a,b) not in seen:
       seen.add((a,b));q.append((a,b))
    comps.append(co)
 return comps
